"""Инструкции сайтов: устройство агрегатора, которого общее наставление не знает,
а снимок страницы не показывает."""

_GEEKJOB = """Правка резюме — одна длинная страница с кнопкой «Сохранить» внизу.
Навыки — блок «Ключевые навыки и стек технологий»; снимок показывает его одной строкой текста, поэтому элементы ниже называй этими селекторами. Порядок сверху вниз:
- «Специализация» и под ней направления — плашки; выбрать: browser_click по .tagbox .chip:not(.selected):text-is("Название"). Выбранная плашка этим селектором не находится, и ответ «не вышло» значит, что она уже выбрана: повторное нажатие сняло бы выбор. После выбора появляется следующий уровень — сними страницу заново.
- Под выбранным направлением — дерево навыков с поиском, само поле в снимке — textbox без подписи. Каждый навык: раскладка из одного пункта с селектором input.vue-treeselect__input, browser_click по .vue-treeselect__control, browser_type названия в input.vue-treeselect__input, затем browser_click по .vue-treeselect__option:not(.vue-treeselect__option--selected) >> text="Название". Сайт пишет «No results found» — навыка в дереве нет: пропусти его. Вариант есть, а селектор его не находит — навык уже отмечен, не нажимай по нему снова. Список закрывает browser_press Escape в input.vue-treeselect__input.
- Убрать навык, которого нет в анкете: browser_click по .vue-treeselect__multi-value-item:has-text("Название") .vue-treeselect__value-remove.
- «Уровень должности» — плашки, как специализация.
- «Дополнительные теги» (поле «+Новый тег») не заполняй; теги, которые там уже есть, убери нажатием по их значку close.
«О себе» — редактор форматированного текста, browser_type в него работает как обычно.
Контактов в резюме нет. Имя, телефон, Telegram, GitHub и прочие способы связи — в «Профиль и контакты» с главной страницы аккаунта my.geekjob.ru; телефон и часть полей появляются после ссылки «+ Добавить социальные сети и другие способы связи». У этой страницы своя кнопка «Сохранить»."""

SITE_GUIDES = {"geekjob.ru": _GEEKJOB}
"""Хост сайта → его инструкция. Ключ — сайт без поддомена: поддомен находит свой сайт."""


def guide_lines(host: str | None) -> list[str]:
    """Строки задания об устройстве сайта; у сайта без инструкции — ни одной."""
    for site, guide in SITE_GUIDES.items():
        if host == site or (host or "").endswith("." + site):
            return ["Устройство этого сайта:", guide]
    return []
